-- 成就第一批（owner 2026-11-23，依「绮梦成就表·修订版」）：對話輪數、單卡輪數兩個新系列，現有阶梯加檔、改名，
-- 留言／獲讚／粉絲／收藏改用防刷口徑（說明見 src/community/badges.ts 的 METRICS）。已發的徽章一律保留（每小時掃描只發不收）。
ALTER TABLE badge_qualifications ADD COLUMN send_turns INTEGER NOT NULL DEFAULT 0 CHECK(send_turns>=0);
ALTER TABLE badge_qualifications ADD COLUMN max_role_turns INTEGER NOT NULL DEFAULT 0 CHECK(max_role_turns>=0);
INSERT INTO community_badge_definitions(key,icon,category,titles,descriptions,created_at,metric,threshold,sort_order) VALUES
('player_explorer_3','compass','play','{"zh-Hant": "初入綺夢", "zh-Hans": "初入绮梦", "en": "First steps in", "ja": "はじめての夢路", "ko": "첫 꿈길"}','{"zh-Hant": "和 3 個不同角色各聊滿 10 輪（每天最多計入 10 個新角色）。", "zh-Hans": "和 3 个不同角色各聊满 10 轮（每天最多计入 10 个新角色）。", "en": "Chat at least 10 rounds each with 3 different characters. Up to 10 new characters count per day.", "ja": "3 人のキャラクターとそれぞれ 10 往復以上会話する（1 日に数えるのは新しいキャラクター 10 人まで）。", "ko": "서로 다른 캐릭터 3명과 각각 10번 이상 대화를 주고받으면 획득해요. 하루에 새 캐릭터는 10명까지 세요."}',1795392000000,'explored_roles',3,60),
('player_turns_50','lantern','play','{"zh-Hant": "輕叩心扉", "zh-Hans": "轻叩心扉", "en": "A gentle knock", "ja": "心のノック", "ko": "마음의 노크"}','{"zh-Hant": "累計聊滿 50 輪（自己的卡不算，每天最多計入 300 輪）。", "zh-Hans": "累计聊满 50 轮（自己的卡不算，每天最多计入 300 轮）。", "en": "Chat 50 rounds in total. Your own cards don''t count, and up to 300 rounds count per day.", "ja": "合計 50 往復会話する（自分のカードは対象外。1 日に数えるのは 300 往復まで）。", "ko": "모두 합쳐 50번 대화를 주고받으면 획득해요. 내 카드는 제외하고, 하루에 300번까지 세요."}',1795392000000,'send_turns',50,330),
