('player_turns_2500','lantern','play','{"zh-Hant": "靈魂共鳴者", "zh-Hans": "灵魂共鸣者", "en": "Kindred soul", "ja": "魂の共鳴者", "ko": "영혼의 공명자"}','{"zh-Hant": "累計聊滿 2,500 輪（自己的卡不算，每天最多計入 300 輪）。", "zh-Hans": "累计聊满 2,500 轮（自己的卡不算，每天最多计入 300 轮）。", "en": "Chat 2,500 rounds in total. Your own cards don''t count, and up to 300 rounds count per day.", "ja": "合計 2,500 往復会話する（自分のカードは対象外。1 日に数えるのは 300 往復まで）。", "ko": "모두 합쳐 2,500번 대화를 주고받으면 획득해요. 내 카드는 제외하고, 하루에 300번까지 세요."}',1795392000000,'send_turns',2500,332),
('player_turns_10000','lantern','play','{"zh-Hant": "織言築夢師", "zh-Hans": "织言筑梦师", "en": "Dreamweaver of words", "ja": "言葉で夢を紡ぐ者", "ko": "말로 꿈을 엮는 자"}','{"zh-Hant": "累計聊滿 10,000 輪（自己的卡不算，每天最多計入 300 輪）。", "zh-Hans": "累计聊满 10,000 轮（自己的卡不算，每天最多计入 300 轮）。", "en": "Chat 10,000 rounds in total. Your own cards don''t count, and up to 300 rounds count per day.", "ja": "合計 10,000 往復会話する（自分のカードは対象外。1 日に数えるのは 300 往復まで）。", "ko": "모두 합쳐 10,000번 대화를 주고받으면 획득해요. 내 카드는 제외하고, 하루에 300번까지 세요."}',1795392000000,'send_turns',10000,333),
