('player_devoted_150','heart','play','{"zh-Hant": "漸入佳境", "zh-Hans": "渐入佳境", "en": "Deeper in", "ja": "物語の深みへ", "ko": "무르익는 이야기"}','{"zh-Hant": "在同一張卡上聊滿 150 輪（自己的卡不算，每天最多計入 300 輪）。", "zh-Hans": "在同一张卡上聊满 150 轮（自己的卡不算，每天最多计入 300 轮）。", "en": "Chat 150 rounds with the same card. Your own cards don''t count, and up to 300 rounds count per day.", "ja": "同じカードと 150 往復会話する（自分のカードは対象外。1 日に数えるのは 300 往復まで）。", "ko": "같은 카드와 150번 대화를 주고받으면 획득해요. 내 카드는 제외하고, 하루에 300번까지 세요."}',1795392000000,'max_role_turns',150,335),
('player_devoted_500','heart','play','{"zh-Hant": "羈絆深鎖", "zh-Hans": "羁绊深锁", "en": "Bound together", "ja": "深き絆", "ko": "깊어진 인연"}','{"zh-Hant": "在同一張卡上聊滿 500 輪（自己的卡不算，每天最多計入 300 輪）。", "zh-Hans": "在同一张卡上聊满 500 轮（自己的卡不算，每天最多计入 300 轮）。", "en": "Chat 500 rounds with the same card. Your own cards don''t count, and up to 300 rounds count per day.", "ja": "同じカードと 500 往復会話する（自分のカードは対象外。1 日に数えるのは 300 往復まで）。", "ko": "같은 카드와 500번 대화를 주고받으면 획득해요. 내 카드는 제외하고, 하루에 300번까지 세요."}',1795392000000,'max_role_turns',500,336),
('player_devoted_1500','heart','play','{"zh-Hant": "白首之約", "zh-Hans": "白首之约", "en": "Together to the end", "ja": "白髪までの約束", "ko": "백년가약"}','{"zh-Hant": "在同一張卡上聊滿 1,500 輪（自己的卡不算，每天最多計入 300 輪）。", "zh-Hans": "在同一张卡上聊满 1,500 轮（自己的卡不算，每天最多计入 300 轮）。", "en": "Chat 1,500 rounds with the same card. Your own cards don''t count, and up to 300 rounds count per day.", "ja": "同じカードと 1,500 往復会話する（自分のカードは対象外。1 日に数えるのは 300 往復まで）。", "ko": "같은 카드와 1,500번 대화를 주고받으면 획득해요. 내 카드는 제외하고, 하루에 300번까지 세요."}',1795392000000,'max_role_turns',1500,337),
('player_commenter_300','chat','social','{"zh-Hant": "綺夢評論家", "zh-Hans": "绮梦评论家", "en": "Resident critic", "ja": "名物評論家", "ko": "명물 평론가"}','{"zh-Hant": "留下 300 則留言（10 個字以上；同一張卡最多計 3 則，每天最多計 5 則）。", "zh-Hans": "留下 300 则留言（10 个字以上；同一张卡最多计 3 则，每天最多计 5 则）。", "en": "Leave 300 comments of at least 10 characters. Up to 3 count per card and 5 per day.", "ja": "10 文字以上のコメントを 300 件残す（1 枚のカードで数えるのは 3 件、1 日 5 件まで）。", "ko": "10자 이상 댓글 300개를 남기세요. 카드 한 장에 3개, 하루에 5개까지 세요."}',1795392000000,'comments',300,82),
('player_liked_5','spark','social','{"zh-Hant": "偶遇知音", "zh-Hans": "偶遇知音", "en": "Kindred ear", "ja": "思わぬ共感", "ko": "뜻밖의 공감"}','{"zh-Hant": "留言累計獲得 5 個讚（自己按的不算，同一個人最多計 3 個，只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "留言累计获得 5 个赞（自己点的不算，同一个人最多计 3 个，只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Receive 5 likes on your comments. Your own likes don''t count, each member counts up to 3, and only members who joined at least 3 days ago and have chatted 3 rounds count.", "ja": "コメントに合計 5 件のいいねをもらう（自分のいいねは対象外。1 人 3 件まで、登録から 3 日以上たち 3 往復以上会話したメンバーのみ）。", "ko": "댓글에 좋아요를 총 5개 받으세요. 내가 누른 좋아요는 제외하고, 한 사람당 3개까지, 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}',1795392000000,'likes_received',5,82),
('player_liked_500','spark','social','{"zh-Hant": "萬眾共鳴之聲", "zh-Hans": "万众共鸣之声", "en": "Voice of the crowd", "ja": "皆が共鳴する声", "ko": "모두가 공감한 목소리"}','{"zh-Hant": "留言累計獲得 500 個讚（自己按的不算，同一個人最多計 3 個，只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "留言累计获得 500 个赞（自己点的不算，同一个人最多计 3 个，只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Receive 500 likes on your comments. Your own likes don''t count, each member counts up to 3, and only members who joined at least 3 days ago and have chatted 3 rounds count.", "ja": "コメントに合計 500 件のいいねをもらう（自分のいいねは対象外。1 人 3 件まで、登録から 3 日以上たち 3 往復以上会話したメンバーのみ）。", "ko": "댓글에 좋아요를 총 500개 받으세요. 내가 누른 좋아요는 제외하고, 한 사람당 3개까지, 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}',1795392000000,'likes_received',500,84),
('creator_followers_300','users','creation','{"zh-Hant": "千呼萬喚的明星", "zh-Hans": "千呼万唤的明星", "en": "Long-awaited star", "ja": "待望のスター", "ko": "모두가 기다린 스타"}','{"zh-Hant": "被 300 位成員關注（只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "被 300 位成员关注（只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Be followed by 300 members who joined at least 3 days ago and have chatted 3 rounds.", "ja": "300 人のメンバーにフォローされる（登録から 3 日以上たち、3 往復以上会話したメンバーのみ）。", "ko": "멤버 300명이 팔로우하면 획득해요. 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}',1795392000000,'followers',300,46),
('creator_favorited_1000','heart','creation','{"zh-Hant": "傳世典藏錄", "zh-Hans": "传世典藏录", "en": "Timeless collection", "ja": "不朽の名作集", "ko": "불멸의 소장품"}','{"zh-Hant": "卡片累計被收藏 1,000 次（自己收藏的不算，只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "卡片累计被收藏 1,000 次（自己收藏的不算，只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Have your cards saved 1,000 times in total by other members who joined at least 3 days ago and have chatted 3 rounds.", "ja": "カードが合計 1,000 回保存される（自分の保存は対象外。登録から 3 日以上たち、3 往復以上会話したメンバーのみ）。", "ko": "카드가 총 1,000번 저장되면 획득해요. 내가 저장한 건 제외하고, 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}',1795392000000,'favorites_received',1000,48),
('rank_same_card_crown','crown','rank','{"zh-Hant": "三合君王", "zh-Hans": "三合君王", "en": "Sovereign of three boards", "ja": "三冠の王", "ko": "세 왕좌의 주인"}','{"zh-Hant": "同一張卡先後拿過日榜、週榜、月榜第一（清水榜或綜合榜都算）。", "zh-Hans": "同一张卡先后拿过日榜、周榜、月榜第一（清水榜或综合榜都算）。", "en": "Have one card reach #1 on a daily, a weekly and a monthly board. SFW and Overall boards both count.", "ja": "同じカードで日間・週間・月間ランキングの 1 位をすべて獲得する（全年齢・総合どちらのランキングでも可）。", "ko": "같은 카드로 일간·주간·월간 랭킹 1위를 모두 차지하면 획득해요. 전연령·종합 랭킹 모두 인정돼요."}',1795392000000,'same_card_crown',1,230);
