UPDATE community_badge_definitions SET titles='{"zh-Hant": "品茗鑑夢人", "zh-Hans": "品茗鉴梦人", "en": "Connoisseur of dreams", "ja": "夢の目利き", "ko": "꿈의 감별사"}',descriptions='{"zh-Hant": "留下 100 則留言（10 個字以上；同一張卡最多計 3 則，每天最多計 5 則）。", "zh-Hans": "留下 100 则留言（10 个字以上；同一张卡最多计 3 则，每天最多计 5 则）。", "en": "Leave 100 comments of at least 10 characters. Up to 3 count per card and 5 per day.", "ja": "10 文字以上のコメントを 100 件残す（1 枚のカードで数えるのは 3 件、1 日 5 件まで）。", "ko": "10자 이상 댓글 100개를 남기세요. 카드 한 장에 3개, 하루에 5개까지 세요."}' WHERE key='player_commenter_100';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "高讚嘴替", "zh-Hans": "高赞嘴替", "en": "Says it for us", "ja": "みんなの代弁者", "ko": "모두의 대변인"}',descriptions='{"zh-Hant": "留言累計獲得 10 個讚（自己按的不算，同一個人最多計 3 個，只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "留言累计获得 10 个赞（自己点的不算，同一个人最多计 3 个，只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Receive 10 likes on your comments. Your own likes don''t count, each member counts up to 3, and only members who joined at least 3 days ago and have chatted 3 rounds count.", "ja": "コメントに合計 10 件のいいねをもらう（自分のいいねは対象外。1 人 3 件まで、登録から 3 日以上たち 3 往復以上会話したメンバーのみ）。", "ko": "댓글에 좋아요를 총 10개 받으세요. 내가 누른 좋아요는 제외하고, 한 사람당 3개까지, 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}' WHERE key='player_liked_10';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "妙嘴生花", "zh-Hans": "妙嘴生花", "en": "Silver tongue", "ja": "言葉の魔術師", "ko": "말솜씨 장인"}',descriptions='{"zh-Hant": "留言累計獲得 100 個讚（自己按的不算，同一個人最多計 3 個，只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "留言累计获得 100 个赞（自己点的不算，同一个人最多计 3 个，只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Receive 100 likes on your comments. Your own likes don''t count, each member counts up to 3, and only members who joined at least 3 days ago and have chatted 3 rounds count.", "ja": "コメントに合計 100 件のいいねをもらう（自分のいいねは対象外。1 人 3 件まで、登録から 3 日以上たち 3 往復以上会話したメンバーのみ）。", "ko": "댓글에 좋아요를 총 100개 받으세요. 내가 누른 좋아요는 제외하고, 한 사람당 3개까지, 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}' WHERE key='player_liked_100';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "初織夢境", "zh-Hans": "初织梦境", "en": "First dream woven", "ja": "はじめての夢織り", "ko": "첫 번째 꿈"}' WHERE key='first_work';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "新銳造夢師", "zh-Hans": "新锐造梦师", "en": "Rising dreamsmith", "ja": "新進の夢職人", "ko": "떠오르는 꿈 장인"}' WHERE key='creator_works_3';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "百巧築夢匠", "zh-Hans": "百巧筑梦匠", "en": "Master dreamsmith", "ja": "夢づくりの名匠", "ko": "꿈 짓는 명장"}' WHERE key='creator_works_10';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "多產幻想家", "zh-Hans": "多产幻想家", "en": "Prolific fantasist", "ja": "多作の幻想家", "ko": "다작의 몽상가"}' WHERE key='creator_works_30';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "納入行囊", "zh-Hans": "纳入行囊", "en": "Packed for the journey", "ja": "旅の荷物に", "ko": "여행 가방 속으로"}',descriptions='{"zh-Hant": "卡片累計被收藏 10 次（自己收藏的不算，只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "卡片累计被收藏 10 次（自己收藏的不算，只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Have your cards saved 10 times in total by other members who joined at least 3 days ago and have chatted 3 rounds.", "ja": "カードが合計 10 回保存される（自分の保存は対象外。登録から 3 日以上たち、3 往復以上会話したメンバーのみ）。", "ko": "카드가 총 10번 저장되면 획득해요. 내가 저장한 건 제외하고, 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}' WHERE key='creator_favorited_10';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "口碑私藏", "zh-Hans": "口碑私藏", "en": "Treasured pick", "ja": "秘蔵の一作", "ko": "소장각"}',descriptions='{"zh-Hant": "卡片累計被收藏 100 次（自己收藏的不算，只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "卡片累计被收藏 100 次（自己收藏的不算，只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Have your cards saved 100 times in total by other members who joined at least 3 days ago and have chatted 3 rounds.", "ja": "カードが合計 100 回保存される（自分の保存は対象外。登録から 3 日以上たち、3 往復以上会話したメンバーのみ）。", "ko": "카드가 총 100번 저장되면 획득해요. 내가 저장한 건 제외하고, 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}' WHERE key='creator_favorited_100';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "小有名氣", "zh-Hans": "小有名气", "en": "Getting noticed", "ja": "ちょっと有名", "ko": "작은 유명인"}',descriptions='{"zh-Hant": "被 10 位成員關注（只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "被 10 位成员关注（只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Be followed by 10 members who joined at least 3 days ago and have chatted 3 rounds.", "ja": "10 人のメンバーにフォローされる（登録から 3 日以上たち、3 往復以上会話したメンバーのみ）。", "ko": "멤버 10명이 팔로우하면 획득해요. 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}' WHERE key='creator_followers_10';
UPDATE community_badge_definitions SET titles='{"zh-Hant": "百粉達人", "zh-Hans": "百粉达人", "en": "A hundred fans", "ja": "百人のファン", "ko": "팬 백 명"}',descriptions='{"zh-Hant": "被 100 位成員關注（只算註冊滿 3 天、聊過 3 輪以上的成員）。", "zh-Hans": "被 100 位成员关注（只算注册满 3 天、聊过 3 轮以上的成员）。", "en": "Be followed by 100 members who joined at least 3 days ago and have chatted 3 rounds.", "ja": "100 人のメンバーにフォローされる（登録から 3 日以上たち、3 往復以上会話したメンバーのみ）。", "ko": "멤버 100명이 팔로우하면 획득해요. 가입한 지 3일이 지나고 3번 이상 대화한 멤버만 세요."}' WHERE key='creator_followers_100';
UPDATE public_catalog_clock SET revision=lower(hex(randomblob(16))) WHERE id=1;
